// Share keyboard behavior across dynamically rendered chat composers.
document.addEventListener('keydown',event=>{
  const input=event.target;
  if(!(input instanceof HTMLTextAreaElement)||!input.matches('#chat-reply textarea, #family-chat-text, #world-chat-text'))return;
  if(event.key!=='Enter'||event.shiftKey||event.ctrlKey||event.altKey||event.metaKey||event.isComposing||event.keyCode===229)return;
  event.preventDefault();
  const button=input.form?.querySelector('button[type=submit],button:not([type])');
  if(event.repeat||!input.value.trim()||!button||button.disabled)return;
  input.form.requestSubmit(button);
});
