function updateTimers(){
  if(!me)return;
  document.querySelectorAll('[data-stay-until]').forEach(el=>{const seconds=Math.max(0,Math.ceil((Number(el.dataset.stayUntil)-gameTime())/1000));el.textContent=Math.floor(seconds/3600)+'h '+Math.floor(seconds%3600/60)+'m '+seconds%60+'s'});
  document.querySelectorAll('[data-stay-fee]').forEach(el=>el.textContent=money(Math.ceil(Number(el.dataset.baseFee)*Math.max(0,Number(el.dataset.ends)-gameTime())/Math.max(1,Number(el.dataset.duration)))));
  document.querySelectorAll('[data-energy]').forEach(el=>el.textContent=Math.min(me.user.benefits.energyMax,estimatedEnergy()));document.querySelectorAll('[data-energy-overflow]').forEach(el=>{const extra=Math.max(0,estimatedEnergy()-me.user.benefits.energyMax);el.textContent=extra?' +'+extra.toLocaleString(gameLocale):''});
  document.querySelectorAll('[data-until]').forEach(button=>{
    const seconds=Math.max(0,Math.ceil((Number(button.dataset.until)-gameTime())/1000));
    const locked=button.dataset.locked==='true'||me.user.xp<Number(button.dataset.xp||0), tired=estimatedEnergy()<Number(button.dataset.cost||0);
    button.disabled=seconds>0||locked||tired;
    button.textContent=seconds?ltext`WAIT ${seconds} SEC`:locked?(button.dataset.locked==='true'?(button.dataset.lockLabel||'ACQUISITION REQUIRED'):ltext('MORE XP REQUIRED')):tired?ltext('REGENERATING ENERGY'):button.dataset.label||'START ACTION';
  });
}
setInterval(updateTimers,1000);
function missions(el){return premium.missions(el)}
function shop(el,category){return premium.shop(el,category)}
async function combat(el){
  el.innerHTML=lhtml('<img class="section-art" src="/images/banner-missions-v3.png" alt="City streets after dark"><h2>Player operations</h2><p class="muted">Permanent personal protection reduces the target’s actual attack chance, damage and stolen cash. Both players need 500 XP. Robbery only takes cash on hand. Operations share a cooldown. Attacking ends your own VIP protection. Successful liquidations cause a 72-hour coma; treatment starts at a rank-scaled $1–100 million and declines over time. Failed attempts cost health; hostages are released after two minutes.</p>');
  try{
    const [d,list]=await Promise.all([catalogData(),api('players')]);if(!el.isConnected)return;
    el.innerHTML+=lhtml`<div class="panel"><h3>VIP bodyguards</h3><p>Buy 30 minutes of protection from player operations for $50,000.</p><button class="btn secondary" id="protect">Hire protection</button></div><div class="panel"><label for="target">Target player</label><input id="target" list="targets" placeholder="Enter a player username"><datalist id="targets">${list.players.map(p=>lhtml`<option value="${esc(p.username)}">${p.xp} XP</option>`).join('')}</datalist></div><div class="missions premium-grid">${d.pvpActions.map(x=>lhtml`<article class="mission photo-card"><div class="image-wrap"><img class="editorial-image" src="/images/${({attack:'crime-assault.png',rob:'crime-mugging.jpg',liquidate:'crime-hit.jpg',hostage:'crime-hostage.jpg'})[x.id]}" alt="${esc(x.name)}" loading="lazy"></div><div class="card-body"><h3>${esc(x.name)}</h3><div class="item">${x.energy} energy · ${x.supplies.ammo} rounds · Weapon tier ${x.supplies.tier} · ${x.id==='hostage'?ltext('25–65% success by target rank (before protection)'):Math.round(x.chance*100)+ltext('% base success')}</div><div class="item">${x.damage} damage · ${x.cooldown/60000} minute cooldown</div><div class="item">${x.id==='rob'?ltext('Loot: up to 10% of target cash · no fixed cap'):x.id==='hostage'?ltext('Target rank raises difficulty and ransom · up to $10,000,000 on a perfect job'):ltext('Reputation and territory pressure')}</div>${x.id==='liquidate'?lhtml('<label>Liquidation rounds (60–10,000)<input id="liquidation-rounds" type="number" min="60" max="10000" step="1" value="60" required></label><p>60 rounds: 35%; 1,000: about 61%; 3,000: 82%; 10,000: 90% before protection. More bullets have diminishing returns. The target may return fire.</p><label class="check"><input type="checkbox" id="anonymous-liquidation"> Anonymous attempt · extra $500,000 (success or failure)</label>'):''}<br><button class="btn" data-pvp="${x.id}" data-until="${me.cooldowns?.find(c=>c.kind==='pvp')?.available_at||0}" data-cost="${x.energy}" data-xp="500" data-label="Launch operation">Launch operation</button></div></article>`).join('')}</div>`;
    updateTimers();
    el.querySelector('#protect').onclick=async()=>{try{await api('protection',{});await refresh();toast(ltext('VIP protection activated.'))}catch(e){toast(e.message,true)}};
    el.querySelectorAll('[data-pvp]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const result=await api('pvp',{kind:b.dataset.pvp,...(b.dataset.pvp==='liquidate'?{rounds:Number(el.querySelector('#liquidation-rounds').value)}:{}),target:el.querySelector('#target').value,anonymous:b.dataset.pvp==='liquidate'&&!!el.querySelector('#anonymous-liquidation')?.checked});await refresh();toast(result.message,!result.success)}catch(e){toast(e.message,true);b.disabled=false}});
  }catch(e){toast(e.message,true)}
}
