 const sections=[['bots','Bot players'],['players','Players'],['referrals','Beta referrals'],['families','Families'],['bulletins','Announcements & events'],['gifts','Complimentary gifts'],['shop','Shop gifts & grant log'],['security','Security log'],['tickets','Support tickets'],['economy','Economy activity'],['languages','Language usage']].filter(([id])=>id!=='languages'||me.user.role==='owner');
