 el.innerHTML=lhtml`<div class="eyebrow">STAFF CONTROL · ${esc(title.toUpperCase())}</div><h2>${me.user.role==='owner'?ltext('Owner Panel'):ltext('Admin Panel')} / ${esc(title)}</h2><nav class="staff-sections" aria-label="Staff sections">${sections.map(([id,name])=>lhtml`<button class="btn ${id===ownerSection?'':'secondary'}" data-owner-section="${id}" aria-current="${id===ownerSection?'page':'false'}" ${id==='tickets'?'data-ticket-badge':''}>${esc(t(name))}</button>`).join('')}</nav><div id="owner-population"></div><div id="owner-economy"></div><div id="owner-section"></div>`;
