function welcomePage(){
 root.innerHTML=lhtml`<main class="welcome"><section class="welcome-hero">${gameLogo('game-logo-welcome')}<div class="eyebrow">LOYALTY IS EARNED. POWER IS TAKEN.</div><h1>Every city has a king.<br><span class="gold">This one is waiting.</span></h1><p>You arrive with a name nobody knows and a debt to nobody. Beneath the lights, fortunes change hands, alliances are tested, and families rise from the streets to the penthouses.</p><p>Build your crew. Own the businesses that keep the city moving. Turn a quiet reputation into an empire they cannot ignore.</p><h2>Do you have what it takes to become The Godfather of the biggest family in the city?</h2><div class="welcome-actions"><button class="btn" id="begin-story">Build your legacy ↗</button><button class="btn secondary" id="welcome-login">Enter the city</button></div></section><section class="welcome-features"><article><span>01 / REPUTATION</span><h3>25 ranks. One throne.</h3><p>Climb from Outsider to The Godfather. Each promotion increases your earnings and your odds. Then earn legacy distinctions without leaving your empire behind.</p></article><article><span>02 / OWNERSHIP</span><h3>The city works for you.</h3><p>Businesses, residences, garages, cars and private aircraft. Build a collection that earns income, opens opportunities and carries your signature.</p></article><article><span>03 / FAMILY</span><h3>No empire stands alone.</h3><p>Bring your allies together. Face rival players. Write your own story in an international multiplayer underworld.</p></article></section><footer>Mafia: The new Era © · v1.25.2<br>${t('Build your empire today')}</footer></main>`;
 document.querySelector('#begin-story').onclick=()=>authPage(true);document.querySelector('#welcome-login').onclick=()=>authPage(false);
}

function showPromotion(){
 if(document.querySelector('dialog[open]'))return;
 document.querySelector('#promotion-dialog')?.remove();
 const p=me?.user.promotion;if(!p)return;
 const dialog=document.createElement('dialog');dialog.id='promotion-dialog';dialog.className='promotion-dialog';dialog.setAttribute('aria-labelledby','promotion-title');
 dialog.innerHTML=lhtml`<div class="eyebrow">${p.distinctions?ltext('YOUR LEGACY GROWS'):ltext('A NEW CHAPTER OF POWER')}</div><div class="promotion-emblem" aria-hidden="true">${p.distinctions?lhtml`<img class="prestige-emblem" src="/icons/prestige-${p.distinctions}.svg" alt="">`:'✦'}</div><h2 id="promotion-title">${esc(p.rank)}</h2>${p.distinctions?lhtml('<p class="gold">Legacy distinction ')+p.distinctions+lhtml('</p>'):''}<p>You earned ${p.steps===1?ltext('a promotion'):p.steps+ltext(' promotions')}. The city is taking notice.</p><div class="promotion-energy"><strong>+${p.energyBonus} maximum energy</strong><span>${p.energyRestored?ltext('Energy fully restored to ')+p.energyMax:ltext('New capacity: ')+p.energyMax+ltext(' · Owner energy override applied')}</span></div><ul class="promotion-rewards"><li>+${p.incomePercent.toLocaleString(gameLocale,{maximumFractionDigits:2})}% crime income</li><li>+${(p.passiveIncomePercent??(Math.sqrt(1+p.incomePercent/100)-1)*100).toLocaleString(gameLocale,{maximumFractionDigits:2})}% passive income</li>${p.chancePoints?lhtml('<li>+')+p.chancePoints.toFixed(2)+lhtml(' percentage points to crime success (up to 95%)</li>'):''}</ul>${p.unlocks.length?lhtml('<h3>New opportunities</h3><ul class="promotion-rewards">')+p.unlocks.map(x=>lhtml('<li>')+esc(x.available?t('{name} — unlocked',{name:t(x.name)}):t('{name} — requires {asset}',{name:t(x.name),asset:t(x.requires)}))+lhtml('</li>')).join('')+lhtml('</ul>'):''}<p class="muted">Your next move starts with more power.</p><p id="promotion-error" role="alert"></p><button class="btn" id="promotion-continue" autofocus>Continue building your empire →</button>`;
 document.body.append(dialog);dialog.showModal();
 const acknowledge=async()=>{const button=dialog.querySelector('button');button.disabled=true;try{await api('promotion/ack',{id:p.id});dialog.close();dialog.remove();await refresh()}catch(error){dialog.querySelector('#promotion-error').textContent=error.message;button.disabled=false}};
 dialog.querySelector('button').onclick=acknowledge;
 dialog.addEventListener('cancel',event=>{event.preventDefault();if(!dialog.querySelector('button').disabled)acknowledge()});
}

mountInputLimits(document);
mountStatFitting(document);
